+// Sales from the till. A dish sold uses one portion of its recipe per `qty`.
+// The ledger is the record of a sale: its "consume" movements carry the ref
+// `sale:<ticket>` and the instant of the sale (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const REF = "sale:";
+
+/** The ledger ref of a ticket's movements. */
+export function saleRef(ticket) {
+  return `${REF}${ticket}`;
+}
+
+/** True for a "consume" movement written by a sale. */
+export function isSaleMovement(movement) {
+  return movement.type === "consume" && typeof movement.ref === "string" && movement.ref.startsWith(REF);
+}
+
+/** The tickets that already used stock. */
+export function soldTickets(store) {
+  return new Set(store.data.movements.filter(isSaleMovement).map((m) => m.ref.slice(REF.length)));
+}
+
+/** Sells `qty` of a dish on a ticket: consumes its ingredients at `at` (the instant of the sale). */
+export function sellDish(store, { ticket, dishId, qty }, { at }) {
+  const dish = getDish(store, dishId);
+  if (!Number.isInteger(qty) || qty < 1) throw new AppError("invalid_qty");
+  const recipe = getRecipe(store, dish.recipeId);
+  return scaled(recipe, qty)
+    .filter((n) => n.qty > 0)
+    .map((n) => ({
+      itemId: n.itemId,
+      batches: consume(store, n.itemId, n.qty, { at, ref: saleRef(ticket) }),
+    }));
+}
